def serial_ports() -> list[dict[str, str]]:
    if os.name == "nt":
        kernel = ctypes.WinDLL("kernel32", use_last_error=True)
        query = kernel.QueryDosDeviceW
        query.argtypes = [ctypes.c_wchar_p, ctypes.c_wchar_p, ctypes.c_uint32]
        query.restype = ctypes.c_uint32
        found = []
        for n in range(1, 257):
            name, target = f"COM{n}", ctypes.create_unicode_buffer(1024)
            if query(name, target, len(target)):
                found.append({"device": name, "description": name})
        return found
    paths = sorted(set(sum((glob.glob(p) for p in ("/dev/ttyUSB*", "/dev/ttyACM*", "/dev/ttyS*", "/dev/ttyAMA*", "/dev/serial/by-id/*")), [])))
    return [{"device": p, "description": os.path.basename(p)} for p in paths]


class SerialConnection:
    """Minimal 8-N-1 serial port with timeout-based reads on Windows and POSIX."""
    def __init__(self, device: str, baud: int):
        self.device, self.baud = device, baud
        self.handle = None
        if os.name == "nt":
            k = ctypes.WinDLL("kernel32", use_last_error=True)
            self._k = k
            k.CreateFileW.argtypes = [ctypes.c_wchar_p, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_void_p]
            name = device if device.startswith("\\\\.\\") else "\\\\.\\" + device
            k.CreateFileW.restype = ctypes.c_void_p
            handle = k.CreateFileW(name, 0xC0000000, 0, None, 3, 0x80, None)
            if handle in (None, ctypes.c_void_p(-1).value):
                raise OSError(ctypes.get_last_error(), f"Cannot open serial port {device}")
            self.handle = handle

            class DCB(ctypes.Structure):
                _fields_ = [("DCBlength", ctypes.c_uint32), ("BaudRate", ctypes.c_uint32),
                    ("fBinary", ctypes.c_uint32, 1), ("fParity", ctypes.c_uint32, 1), ("fOutxCtsFlow", ctypes.c_uint32, 1),
                    ("fOutxDsrFlow", ctypes.c_uint32, 1), ("fDtrControl", ctypes.c_uint32, 2), ("fDsrSensitivity", ctypes.c_uint32, 1),
                    ("fTXContinueOnXoff", ctypes.c_uint32, 1), ("fOutX", ctypes.c_uint32, 1), ("fInX", ctypes.c_uint32, 1),
                    ("fErrorChar", ctypes.c_uint32, 1), ("fNull", ctypes.c_uint32, 1), ("fRtsControl", ctypes.c_uint32, 2),
                    ("fAbortOnError", ctypes.c_uint32, 1), ("fDummy2", ctypes.c_uint32, 17), ("wReserved", ctypes.c_uint16),
                    ("XonLim", ctypes.c_uint16), ("XoffLim", ctypes.c_uint16), ("ByteSize", ctypes.c_ubyte), ("Parity", ctypes.c_ubyte),
                    ("StopBits", ctypes.c_ubyte), ("XonChar", ctypes.c_byte), ("XoffChar", ctypes.c_byte), ("ErrorChar", ctypes.c_byte),
                    ("EofChar", ctypes.c_byte), ("EvtChar", ctypes.c_byte), ("wReserved1", ctypes.c_uint16)]
            k.GetCommState.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            k.SetCommState.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            k.CloseHandle.argtypes = [ctypes.c_void_p]
            dcb = DCB(); dcb.DCBlength = ctypes.sizeof(DCB)
            if not k.GetCommState(handle, ctypes.byref(dcb)):
                self.close(); raise OSError(ctypes.get_last_error(), "Cannot read serial port settings")
            dcb.BaudRate, dcb.ByteSize, dcb.Parity, dcb.StopBits = baud, 8, 0, 0
            dcb.fBinary, dcb.fParity, dcb.fOutxCtsFlow, dcb.fOutxDsrFlow = 1, 0, 0, 0
            dcb.fOutX, dcb.fInX, dcb.fDtrControl, dcb.fRtsControl = 0, 0, 1, 1
            if not k.SetCommState(handle, ctypes.byref(dcb)):
                self.close(); raise OSError(ctypes.get_last_error(), "Cannot set serial port settings")
            class Timeouts(ctypes.Structure):
                _fields_ = [("ReadIntervalTimeout", ctypes.c_uint32), ("ReadTotalTimeoutMultiplier", ctypes.c_uint32),
                    ("ReadTotalTimeoutConstant", ctypes.c_uint32), ("WriteTotalTimeoutMultiplier", ctypes.c_uint32),
                    ("WriteTotalTimeoutConstant", ctypes.c_uint32)]
            k.SetCommTimeouts.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            t = Timeouts(0xFFFFFFFF, 0, 200, 0, 2000)
            if not k.SetCommTimeouts(handle, ctypes.byref(t)):
                self.close(); raise OSError(ctypes.get_last_error(), "Cannot configure serial read timeout")
        else:
            import fcntl
            import termios
            rate = getattr(termios, f"B{baud}", None)
            if rate is None:
                raise ValueError(f"Baud rate {baud} is not supported by this platform.")
            self.fd = os.open(device, os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
            attrs = termios.tcgetattr(self.fd)
            attrs[0] = 0; attrs[1] = 0; attrs[2] = termios.CLOCAL | termios.CREAD | termios.CS8
            attrs[3] = 0; attrs[4] = rate; attrs[5] = rate
            attrs[6][termios.VMIN] = 0; attrs[6][termios.VTIME] = 2
            termios.tcsetattr(self.fd, termios.TCSANOW, attrs)
            self._fcntl, self._termios = fcntl, termios

    def read(self, size: int) -> bytes:
        if os.name == "nt":
            buf = ctypes.create_string_buffer(size); got = ctypes.c_uint32()
            self._k.ReadFile.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint32, ctypes.POINTER(ctypes.c_uint32), ctypes.c_void_p]
            if not self._k.ReadFile(self.handle, buf, size, ctypes.byref(got), None):
                err = ctypes.get_last_error()
                if err in (995, 1167): return b""
                raise OSError(err, "Serial read failed")
            return buf.raw[:got.value]
        import select
        ready, _, _ = select.select([self.fd], [], [], .2)
        return os.read(self.fd, size) if ready else b""

    def write(self, data: bytes) -> None:
        if os.name == "nt":
            buf = ctypes.create_string_buffer(data); sent = ctypes.c_uint32()
            self._k.WriteFile.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint32, ctypes.POINTER(ctypes.c_uint32), ctypes.c_void_p]
            if not self._k.WriteFile(self.handle, buf, len(data), ctypes.byref(sent), None):
                raise OSError(ctypes.get_last_error(), "Serial write failed")
        else:
            view = memoryview(data)
            while view:
                n = os.write(self.fd, view); view = view[n:]

    def close(self) -> None:
        if os.name == "nt" and self.handle:
            self._k.CloseHandle(self.handle); self.handle = None
        elif hasattr(self, "fd"):
            try: os.close(self.fd)
            except OSError: pass
            del self.fd


def auto_baud(device: str) -> tuple[int, str]:
    rates = (115200, 9600, 19200, 38400, 57600, 4800, 2400, 1200, 230400, 460800)
    ranked: list[tuple[float, int, bytes]] = []
    for rate in rates:
        try:
            conn = SerialConnection(device, rate)
            try:
                import time
                time.sleep(.22)
                sample = conn.read(512)
            finally:
                conn.close()
            if not sample:
                continue
            readable = sum(b in (9, 10, 13) or 32 <= b <= 126 for b in sample) / len(sample)
            diversity = min(len(set(sample)) / 20, 1)
            ranked.append((readable * .8 + diversity * .2, rate, sample))
        except Exception:
            continue
    if not ranked:
        raise RuntimeError("No serial output was detected while probing common baud rates. Ensure the device is transmitting, then retry.")
    ranked.sort(reverse=True, key=lambda item: item[0])
    quality, rate, sample = ranked[0]
    if quality < .50:
        raise RuntimeError("Could not identify a readable baud rate from the device output. Select a rate manually or ensure the device is transmitting text.")
    return rate, sample.decode("utf-8", errors="replace")


